import { useEffect, useState } from "react";
import api from "./api";

export default function CodeEditorPage() {
  const userId = localStorage.getItem("userId");

  const [code, setCode] = useState("");
  const [levels, setLevels] = useState([]);
  const [currentLevel, setCurrentLevel] = useState(null);
  const [level, setLevel] = useState(null);

  const [userInput, setUserInput] = useState("");
  const [output, setOutput] = useState("");
  const [loading, setLoading] = useState(false);

  /* ================= LOAD LEVELS ================= */
  useEffect(() => {
    async function loadLevels() {
      const res = await api.get(`/levels/${userId}`);
      setLevels(res.data.levels);
      setCurrentLevel(res.data.currentLevel);
    }
    loadLevels();
  }, [userId]);

  /* ================= LOAD CURRENT LEVEL ================= */
  useEffect(() => {
    if (!currentLevel) return;

    async function loadCurrentLevel() {
      const res = await api.get(`/level/${userId}`);
      setLevel(res.data.level);
      setCode("");
      setUserInput("");
      setOutput("");
    }
    loadCurrentLevel();
  }, [currentLevel, userId]);

  /* ================= RUN ================= */
  const handleRun = async () => {
    setLoading(true);
    setOutput("");

    try {
      const res = await api.post("/run", {
        code,
        language: "python",
        stdin: userInput,
        userId,
      });
      setOutput(res.data.userOutput || "");
    } catch (err) {
      setOutput(err.response?.data?.message || "Execution error");
    } finally {
      setLoading(false);
    }
  };

  /* ================= SUBMIT ================= */
  const handleSubmit = async () => {
    setLoading(true);
    setOutput("");

    try {
      const res = await api.post("/run", {
        code,
        language: "python",
        stdin: userInput,
        userId,
      });

      setOutput(res.data.userOutput || "");

      if (res.data.success) {
        alert("✅ Correct! Next level unlocked");
        window.location.reload();
      } else {
        alert("❌ Wrong Answer");
      }
    } catch (err) {
      setOutput(err.response?.data?.message || "Execution error");
    } finally {
      setLoading(false);
    }
  };

  if (!level) return <h2 style={{ color: "white" }}>Loading...</h2>;

  return (
    <div style={styles.app}>
      <h1 style={styles.logo}>DailyCode</h1>

      <div style={styles.body}>
        {/* LEVELS */}
        <div style={styles.sidebar}>
          <h3>Levels</h3>
          {levels.map((l) => (
            <button
              key={l.level_no}
              style={{
                ...styles.levelBtn,
                ...(l.level_no === currentLevel
                  ? styles.current
                  : l.level_no < currentLevel
                  ? styles.completed
                  : styles.locked),
              }}
              disabled={l.level_no > currentLevel}
              onClick={async () => {
                if (l.level_no > currentLevel) return;
                const res = await api.get(`/level/${userId}/${l.level_no}`);
                setLevel(res.data.level);
                setCode("");
                setUserInput("");
                setOutput("");
              }}
            >
              Level {l.level_no}
            </button>
          ))}
        </div>

        {/* EDITOR */}
        <div style={styles.main}>
          <h2>
            Level {level.level_no}: {level.title}
          </h2>

          <p>{level.description}</p>

          <textarea
            value={code}
            onChange={(e) => setCode(e.target.value)}
            placeholder="Write your Python code here..."
            style={styles.editor}
          />

          <div>
            <button onClick={handleRun} style={styles.runBtn}>▶ Run</button>
            <button onClick={handleSubmit} style={styles.submitBtn}>✔ Submit</button>
          </div>

          <div style={styles.grid}>
            <div style={styles.box}>
              <h4>Sample Input</h4>
              <pre>{level.input_data || "N/A"}</pre>
            </div>

            <div style={styles.box}>
              <h4>Your Input (optional)</h4>
              <textarea
                value={userInput}
                onChange={(e) => setUserInput(e.target.value)}
                style={styles.userInput}
              />
            </div>

            <div style={styles.box}>
              <h4>Expected Output</h4>
              <pre>{level.expected_output}</pre>
            </div>

            <div style={styles.box}>
              <h4>Your Output</h4>
              <pre>{loading ? "Running..." : output || "—"}</pre>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ================= STYLES ================= */
const styles = {
  app: { background: "#0f172a", color: "white", minHeight: "100vh", padding: 20 },
  logo: { color: "#38bdf8" },
  body: { display: "flex", gap: 20 },
  sidebar: { width: 180 },
  levelBtn: { width: "100%", padding: 8, marginBottom: 6 },
  current: { background: "#4caf50" },
  completed: { background: "#2196f3" },
  locked: { background: "#475569" },
  main: { flex: 1 },
  editor: {
    width: "100%",
    height: 250,
    background: "#020617",
    color: "white",
    padding: 10,
    fontFamily: "monospace",
  },
  runBtn: { background: "#2563eb", color: "white", padding: "6px 14px" },
  submitBtn: {
    background: "#16a34a",
    color: "white",
    padding: "6px 14px",
    marginLeft: 10,
  },
  grid: { display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginTop: 20 },
  box: { background: "#1e293b", padding: 10 },
  userInput: { width: "100%", height: 50 },
};
